// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame, ERC20Interface} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    bool ret;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(address tokenOwner, uint256 amount) public {
        // tokenOwner must look like a plain EOA: nonzero, no code
        vm.assume(tokenOwner != address(0));
        vm.assume(tokenOwner.code.length == 0);
        vm.assume(tokenOwner != address(this));

        TrueToken token = new TrueToken();
        ret = true;

        // the owner of c is address(this) (setUp), so the onlyOwner gate passes
        bool ok;
        try c.transferAnyERC20Token(address(token), tokenOwner, amount) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // GENERAL RULE: for a token whose transfer returns true, transferAnyERC20Token
        // must complete and return exactly that token's result (true).
        // The mutant calls the token at `tokenOwner` (a codeless EOA): the low-level
        // call 'succeeds' with EMPTY returndata, and decoding a bool from empty data
        // reverts, so ok == false on the buggy version.
        assertTrue(ok);
    }
}

contract TrueToken is ERC20Interface {
    function transfer(address to, uint256 tokens) override public returns (bool success) {
        return true;
    }
}
